'use client';

import { useFormState, useFormStatus } from 'react-dom';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useEffect } from 'react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import { submitContactForm, type ContactFormState } from './actions';
import { Loader2 } from 'lucide-react';

const ContactFormSchema = z.object({
  name: z.string().min(2, { message: "Name must be at least 2 characters." }),
  email: z.string().email({ message: "Invalid email address." }),
  company: z.string().optional(),
  message: z.string().min(10, { message: "Message must be at least 10 characters." }),
});

type ContactFormData = z.infer<typeof ContactFormSchema>;

function SubmitButton() {
  const { pending } = useFormStatus();
  return (
    <Button type="submit" disabled={pending} className="w-full md:w-auto">
      {pending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
      Send Message
    </Button>
  );
}

export default function ContactForm() {
  const { toast } = useToast();
  const initialState: ContactFormState = { message: '', status: 'idle' };
  const [state, formAction] = useFormState(submitContactForm, initialState);

  const {
    register,
    handleSubmit,
    formState: { errors },
    reset,
  } = useForm<ContactFormData>({
    resolver: zodResolver(ContactFormSchema),
  });

  useEffect(() => {
    if (state.status === 'success') {
      toast({
        title: 'Message Sent!',
        description: state.message,
      });
      reset(); // Reset form fields
    } else if (state.status === 'error' && state.message && !state.errors) {
      // General error not related to specific fields
      toast({
        title: 'Error',
        description: state.message,
        variant: 'destructive',
      });
    }
  }, [state, toast, reset]);

  const fieldErrors = state.errors || {};

  return (
    <form action={formAction} className="space-y-6">
      <div>
        <Label htmlFor="name">Full Name</Label>
        <Input id="name" {...register('name')} placeholder="John Doe" aria-invalid={!!errors.name || !!fieldErrors.name} />
        {(errors.name || fieldErrors.name) && (
          <p className="text-sm text-destructive mt-1">{errors.name?.message || fieldErrors.name?.[0]}</p>
        )}
      </div>

      <div>
        <Label htmlFor="email">Email Address</Label>
        <Input id="email" type="email" {...register('email')} placeholder="you@example.com" aria-invalid={!!errors.email || !!fieldErrors.email} />
        {(errors.email || fieldErrors.email) && (
          <p className="text-sm text-destructive mt-1">{errors.email?.message || fieldErrors.email?.[0]}</p>
        )}
      </div>

      <div>
        <Label htmlFor="company">Company (Optional)</Label>
        <Input id="company" {...register('company')} placeholder="Your Company Inc." aria-invalid={!!errors.company || !!fieldErrors.company} />
        {(errors.company || fieldErrors.company) && (
          <p className="text-sm text-destructive mt-1">{errors.company?.message || fieldErrors.company?.[0]}</p>
        )}
      </div>

      <div>
        <Label htmlFor="message">Your Message</Label>
        <Textarea id="message" {...register('message')} placeholder="How can we help you achieve digital domination?" rows={5} aria-invalid={!!errors.message || !!fieldErrors.message} />
        {(errors.message || fieldErrors.message) && (
          <p className="text-sm text-destructive mt-1">{errors.message?.message || fieldErrors.message?.[0]}</p>
        )}
      </div>
      
      <SubmitButton />
    </form>
  );
}
